class Logger implements AutoCloseable {
    private final String name;
    Logger(String name) {
        this.name = name;
        System.out.println("[open] " + name);
    }
    void log(String msg) {
        System.out.println("[" + name + "] " + msg);
    }
    @Override
    public void close() {
        System.out.println("[close] " + name);
    }
}

public class Main {
    public static void main(String[] args) {
        try (Logger outer = new Logger("outer");
             Logger inner = new Logger("inner")) {
            outer.log("starting work");
            inner.log("doing detail work");
        }
        System.out.println("done");
    }
}
